#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int smallestRangeII(vector<int>& A, int K) {
        sort(A.begin(), A.end());
        int n = A.size();
        int result = A[n - 1] - A[0];

        for (int i = 0; i < n - 1; ++i) {
            int maxVal = max(A[n - 1] - K, A[i] + K);
            int minVal = min(A[0] + K, A[i + 1] - K);
            result = min(result, maxVal - minVal);
        }

        return result;
    }
};
